      `Submitted: ${JSON.stringify(Object.fromEntries([...new Set(data.keys())].map((name) => [name, q.questions.find((item) => item.name === name)?.kind === 'multiple' || data.getAll(name).length > 1 ? data.getAll(name) : data.get(name)])))}`,
