        report(
          `Current checkpoint: ${q.questions.find((item) => item.name === event.detail.value)?.title}`,
        );
    };
    if (kind === 'controlled') report(`Current checkpoint: ${questions[0].title}`);
  }
  if (kind === 'resume') {
    q.defaultItem = 'verification';
